import numpy as np
def solution(seq_len, head_dim, theta=10000.0):
    if head_dim <= 0 or head_dim % 2: raise ValueError("head_dim must be positive and even")
    inv = 1.0 / (theta ** (np.arange(0, head_dim, 2, dtype=float) / head_dim))
    pos = np.arange(seq_len, dtype=float)[:, None]
    angles = pos * inv[None, :]
    return {"cos": np.cos(angles).tolist(), "sin": np.sin(angles).tolist()}

import numpy as np
def solution(q, k, v, causal=False):
    q=np.asarray(q,dtype=float); k=np.asarray(k,dtype=float); v=np.asarray(v,dtype=float)
    # Inputs are [heads, sequence, head_dim]; K/V heads are repeated to query-head count.
    h=q.shape[0]
    if h % k.shape[0]: raise ValueError("query heads must be divisible by KV heads")
    k=np.repeat(k,h//k.shape[0],axis=0); v=np.repeat(v,h//v.shape[0],axis=0)
    scores=q@np.swapaxes(k,-1,-2)/np.sqrt(q.shape[-1])
    if causal:
        mask=np.triu(np.ones(scores.shape[-2:],dtype=bool),k=1)
        scores=np.where(mask,-1e30,scores)
    e=np.exp(scores-scores.max(axis=-1,keepdims=True)); p=e/e.sum(axis=-1,keepdims=True)
    return (p@v).tolist()

