def solution(x, expert_weights, router_logits, top_k=1):
    x=np.asarray(x,dtype=float); ew=np.asarray(expert_weights,dtype=float); logits=np.asarray(router_logits,dtype=float)
    if ew.ndim!=3 or logits.shape[-1]!=ew.shape[0]: raise ValueError("expert_weights must be [experts,in,out]")
    idx=np.argsort(logits,axis=-1)[...,-top_k:][...,::-1]
    vals=np.take_along_axis(logits,idx,axis=-1); probs=np.exp(vals-vals.max(axis=-1,keepdims=True)); probs/=probs.sum(axis=-1,keepdims=True)
    out=np.zeros(x.shape[:-1]+(ew.shape[-1],),dtype=float)
    for j in range(top_k):
        ids=idx[...,j]; weights=probs[...,j]
        # This simple reference expects one router row per token (x shape [tokens,features]).
        for t in range(x.shape[0]): out[t]+=weights[t]*(x[t]@ew[ids[t]])
