    pairs=int(rotary_pairs)
    if pairs<0 or 2*pairs>x.shape[-1]: raise ValueError("rotary_pairs out of range")
    if pairs:
        dim=2*pairs; sub=x[...,:dim]; pos=np.asarray(positions,dtype=float)
        inv=1/(10000.0**(np.arange(0,dim,2,dtype=float)/dim)); ang=pos[...,None]*inv
        c,s=np.cos(ang),np.sin(ang)
        out[...,:dim:2]=sub[...,0::2]*c-sub[...,1::2]*s
        out[...,1:dim:2]=sub[...,0::2]*s+sub[...,1::2]*c
    return out.tolist()

